    state->dataBSDFWindow->ComplexWind.allocate(ISurf);
    state->dataBSDFWindow->ComplexWind(ISurf).NumStates = NumStates;
    state->dataBSDFWindow->ComplexWind(ISurf).Geom.allocate(NumStates);

